#!/usr/bin/env python3
"""Generate the platform design-token files from AnixOps Design and apps/ios/Design/tokens.json.

    python3 .github/scripts/design_tokens.py          # rewrite the generated files
    python3 .github/scripts/design_tokens.py --check  # exit 1 if they are stale (CI)

apps/ios/Design/tokens.json maps AnixOps Net's token names onto AnixOps Design tokens; the values come from the
vendored AnixOps Design tokens.json (see .github/scripts/sync_design.py). Outputs:

    apps/ios/Sources/NetworkCoreAppHost/BrandTokens.swift   (iOS, iPadOS, macOS, widget)
    apps/windows-gui/ui/src/design/tokens.css               (Windows and Linux desktop: aliases over the
                                                             vendored tokens.css, which styles.css imports first)

Standard library only, so CI needs nothing but python3.
"""

from __future__ import annotations

import json
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SOURCE = ROOT / "apps/ios/Design/tokens.json"
SWIFT_OUT = ROOT / "apps/ios/Sources/NetworkCoreAppHost/BrandTokens.swift"
CSS_OUT = ROOT / "apps/windows-gui/ui/src/design/tokens.css"

THEMES = ("light", "dark")
HEADER = (
    "Generated by .github/scripts/design_tokens.py from apps/ios/Design/tokens.json and AnixOps Design {version}. "
    "Do not edit."
)
WEIGHTS = ("regular", "medium", "semibold", "bold")
HEX = re.compile(r"^#([0-9A-Fa-f]{6})$")
RGBA = re.compile(r"^rgba\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*([0-9.]+)\s*\)$")


def fail(message: str) -> None:
    sys.exit(f"design_tokens: {message}")


def kebab(name: str) -> str:
    return re.sub(r"(?<=[a-z0-9])([A-Z0-9])", r"-\1", name).lower()


def number(value: float) -> str:
    return str(int(value)) if float(value).is_integer() else repr(round(float(value), 4))


def value_of(node: object, where: str) -> object:
    if not isinstance(node, dict) or "$value" not in node:
        fail(f"{where} is not an AnixOps Design token")
    return node["$value"]


def lookup(upstream: dict, path: str, where: str) -> object:
    node: object = upstream
    for part in path.split("."):
        if not isinstance(node, dict) or part not in node:
            fail(f"{where} refers to {path}, which AnixOps Design does not define")
        node = node[part]
    return value_of(node, path)


def swift_color(value: str, where: str) -> str:
    if match := HEX.match(value):
        return f"Color(hex: 0x{match.group(1).upper()})"
    if match := RGBA.match(value):
        red, green, blue, alpha = match.groups()
        hex_value = f"{int(red):02X}{int(green):02X}{int(blue):02X}"
        return f"Color(hex: 0x{hex_value}, opacity: {number(float(alpha))})"
    fail(f"{where} = {value!r} is neither #RRGGBB nor rgba()")
    return ""


def px(value: str, where: str) -> float:
    if not isinstance(value, str) or not value.endswith("px"):
        fail(f"{where} = {value!r} is not a px length")
    return float(value[:-2])


def ms(value: str, where: str) -> float:
    if not isinstance(value, str) or not value.endswith("ms"):
        fail(f"{where} = {value!r} is not a ms duration")
    return float(value[:-2])


def brand_colors(tokens: dict, upstream: dict) -> dict[str, str]:
    colors = upstream["color"]
    return {name: lookup(colors, ref, f"brand.{name}") for name, ref in tokens["brand"].items()}


def palette(tokens: dict, upstream: dict, theme: str) -> dict[str, str]:
    colors = upstream["color"]
    out = {}
    for key, ref in tokens["palette"].items():
        path = ref[theme] if isinstance(ref, dict) else ref
        if "." not in path:
            path = f"{theme}.{path}"
        out[key] = lookup(colors, path, f"palette.{key}")
    return out


def swift(tokens: dict, upstream: dict, version: str) -> str:
    out = [f"// {HEADER.format(version=version)}", "// swiftlint:disable all", "", "import SwiftUI", ""]

    out += ["/// AnixOps Design brand colors, the same in every theme. Brand moments only: never controls or body text.",
            "enum Brand {"]
    for name, value in brand_colors(tokens, upstream).items():
        out.append(f"    static let {name} = {swift_color(value, 'brand.' + name)}")
    out += ["}", ""]

    out += ["extension BrandPalette {"]
    for theme in THEMES:
        colors = palette(tokens, upstream, theme)
        out.append(f"    static let {theme} = BrandPalette(")
        lines = [f"        {key}: {swift_color(value, f'{theme}.{key}')}" for key, value in colors.items()]
        out.append(",\n".join(lines))
        out.append("    )")
        out.append("")
    out[-1] = "}"
    out.append("")

    radius = upstream["radius"]
    out += ["/// Corner radii in points (AnixOps Design radius steps).", "enum BrandRadius {"]
    for name, step in tokens["radius"].items():
        out.append(f"    static let {name}: CGFloat = {number(px(lookup(radius, step, 'radius.' + name), step))}")
    out += ["}", ""]

    space = upstream["space"]
    out += ["/// Spacing steps in points (AnixOps Design 4/8 pt grid).", "enum BrandSpacing {"]
    for name, step in tokens["spacing"].items():
        out.append(f"    static let {name}: CGFloat = {number(px(lookup(space, step, 'spacing.' + name), step))}")
    out += ["}", ""]

    motion = tokens["motion"]
    durations = upstream["motion"]["duration"]

    def seconds(key: str) -> str:
        return number(ms(lookup(durations, motion[key], f"motion.{key}"), motion[key]) / 1000)

    out += [
        "/// Animation timings (AnixOps Design motion). Views fall back to a plain fade when Reduce Motion is on.",
        "enum BrandMotion {",
        f"    static let micro: Double = {seconds('micro')}",
        f"    static let standard: Double = {seconds('standard')}",
        f"    static let emphasis: Double = {seconds('emphasis')}",
        f"    static let page: Double = {seconds('page')}",
        f"    static let connectDraw: Double = {number(motion['connectDrawMs'] / 1000)}",
        "    static let spring = Animation.spring("
        f"response: {number(motion['spring']['response'])}, "
        f"dampingFraction: {number(motion['spring']['dampingFraction'])})",
        "}",
        "",
    ]

    out += ["/// The type scale. Every style scales with Dynamic Type.", "enum BrandFont {"]
    for name, style in tokens["typography"].items():
        if style["weight"] not in WEIGHTS:
            fail(f"typography.{name}.weight = {style['weight']!r} is unknown")
        out.append(f"    static let {name} = Font.{style['ios']}.weight(.{style['weight']})")
    out += ["}", ""]
    return "\n".join(out)


def css(tokens: dict, upstream: dict, version: str) -> str:
    known = set(re.findall(r"--([a-z0-9-]+)\s*:", (ROOT / tokens["upstream"]).with_name("tokens.css").read_text("utf-8")))
    brand = brand_colors(tokens, upstream)
    known |= {f"net-{kebab(name)}" for name in brand}
    out = [
        f"/* {HEADER.format(version=version)} */",
        "/* AnixOps Net names over the AnixOps Design variables in ./anixops/tokens.css, which defines both themes:",
        "   these aliases resolve per theme because they are declared on the same root element. */",
        "",
        ":root {",
    ]
    for name, value in brand.items():
        out.append(f"  --net-{kebab(name)}: {value.lower() if HEX.match(value) else value};")
    for name, ref in tokens["desktop"].items():
        if ref not in known:
            fail(f"desktop.{name} refers to --{ref}, which neither AnixOps Design nor brand defines")
        out.append(f"  --{name}: var(--{ref});")
    type_steps = upstream["type"]
    for name, style in tokens["typography"].items():
        step = type_steps.get(style["desktop"])
        if step is None:
            fail(f"typography.{name}.desktop = {style['desktop']!r} is not an AnixOps Design type step")
        weight = {"regular": 400, "medium": 500, "semibold": 600, "bold": 700}[style["weight"]]
        size = number(px(value_of(step, style["desktop"])["fontSize"], style["desktop"]))
        line = number(value_of(step, style["desktop"])["lineHeight"])
        out.append(f"  --font-{name}: {weight} {size}px/{line} var(--font-sans);")
    out += ["}", ""]
    return "\n".join(out)


def main() -> None:
    check = "--check" in sys.argv[1:]
    tokens = json.loads(SOURCE.read_text(encoding="utf-8"))
    if tokens.get("version") != 3:
        fail("tokens.json version must be 3")
    upstream_path = ROOT / tokens["upstream"]
    upstream = json.loads(upstream_path.read_text(encoding="utf-8"))
    version = (upstream_path.with_name("VERSION")).read_text(encoding="utf-8").strip()
    stale = []
    for path, text in ((SWIFT_OUT, swift(tokens, upstream, version)), (CSS_OUT, css(tokens, upstream, version))):
        current = path.read_text(encoding="utf-8") if path.exists() else None
        if current == text:
            continue
        if check:
            stale.append(str(path.relative_to(ROOT)))
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text, encoding="utf-8")
            print(f"wrote {path.relative_to(ROOT)}")
    if stale:
        fail("stale generated files: " + ", ".join(stale) + ". Run python3 .github/scripts/design_tokens.py.")


if __name__ == "__main__":
    main()
